# tls.conf: nginx ends TLS on port 443 and passes plain HTTP to the app.
server {
    listen 443 ssl;
    server_name localhost;

    # The certificate and private key you made with openssl.
    ssl_certificate     /etc/nginx/certs/localhost.crt;
    ssl_certificate_key /etc/nginx/certs/localhost.key;

    location / {
        # "whoami" is the app container's name on the Docker network.
        proxy_pass http://whoami:80;
        # Tell the app what the client really asked for, and who asked.
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}

# lb.conf: nginx receives every request and spreads them across two app containers.
upstream hello {
    # The two copies of hello-devops, by container name and port.
    server app1:8000;
    server app2:8000;
}

server {
    listen 80;

    location / {
        proxy_pass http://hello;
        # Give up on a dead copy after 2 seconds and try the other one.
        # The default is 60 seconds, which feels like a hang.
        proxy_connect_timeout 2s;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }
}

